 "content": "from collections import Counter


def transform(grid):
    """Copy the populated tile into the otherwise blank tiles separated by 4s."""
    h, w = len(grid), len(grid[0])
    sep = 4
    bg = Counter(v for row in grid for v in row if v != sep).most_common(1)[0][0]

    row_cuts = [r for r in range(h) if all(v == sep for v in grid[r])]
    col_cuts = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]

    def spans(size, cuts):
        out, start = [], 0
        for cut in cuts:
            if cut > start:
                out.append((start, cut))
            start = cut + 1
        if start < size:
            out.append((start, size))
        return out

    rows = spans(h, row_cuts)
    cols = spans(w, col_cuts)
    tiles = [(r0, r1, c0, c1) for r0, r1 in rows for c0, c1 in cols]
    if not tiles:
        return [row[:] for row in grid]

    def activity(tile):
        r0, r1, c0, c1 = tile
        return sum(grid[r][c] != bg and grid[r][c] != sep
                   for r in range(r0, r1) for c in range(c0, c1))

    source = max(tiles, key=activity)
    sr0, sr1, sc0, sc1 = source
    if activity(source) == 0:
        return [row[:] for row in grid]
    pattern = [row[sc0:sc1] for row in grid[sr0:sr1]]
    out = [row[:] for row in grid]
    for tile in tiles:
        r0, r1, c0, c1 = tile
        if tile == source or (r1-r0, c1-c0) != (sr1-sr0, sc1-sc0):
            continue
        if activity(tile) == 0:
            for dr, row in enumerate(pattern):
                out[r0+dr][c0:c1] = row[:]
    return out
